/**
 * The emitted C# SDKs through the build and format gates (contract 45 §7.6, Fb4, Fb8): every document fixture
 * builds with no diagnostic under warnings as errors, nullable, the AOT and trim analyzers and the doc file, and
 * leaves `dotnet format whitespace --folder --verify-no-changes` nothing to change, the vendored runtime as
 * committed included; so does the test driver under its own root `.editorconfig`. The gates can fail: the canary's
 * unused local and mis-indented line, and one method of an emitted client re-indented under the `@generated`
 * marker. No emitted text suppresses a diagnostic or marks itself generated, and every file's `using` lines are
 * sorted, each one used: an unused one builds clean, so only the text holds it.
 */
import { mkdirSync, mkdtempSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { describe, expect, it } from "vitest"
import { compiledCSharp } from "./__fixtures__/compiled.ts"
import { csharpCacheDir, runDotnet, withDotnet } from "./__fixtures__/csharp-env.ts"
import { type CSharpFixture, FIXTURES } from "./__fixtures__/documents.ts"
import { generateCSharpSdk } from "./sdk.ts"
import { type CSharpRuntimeFeatures, runtimeFiles } from "./transport.ts"

/** Whether .NET is here: a missing SDK fails where it is required and skips these legs elsewhere (csharp-env). */
const DOTNET = withDotnet()

/** Every document fixture of the registry: each SDK the gates hold, its `client.Safe` mirror in it (bit 21 i5), the
 * streams among them (contract 50 §4.1). */
const GATED = [
	"errors",
	"fixtures",
	"http",
	"lenient",
	"long",
	"realtime",
	"relative",
	"sse",
	"surface",
	"types",
	"ws",
] as const
type Gated = (typeof GATED)[number]

/* what each gated SDK's ops need of the runtime beyond plain HTTP (contract 50 §2): only these three have a WebSocket
 * or realtime op; SSE is core */
const MIXES: Partial<Record<Gated, CSharpRuntimeFeatures>> = {
	long: { realtime: true, ws: true },
	realtime: { realtime: true, ws: false },
	ws: { realtime: false, ws: true },
}
const HTTP_ONLY: CSharpRuntimeFeatures = { realtime: false, ws: false }

const MARKER = "// @generated by honey. DO NOT EDIT."

type Files = Readonly<Record<string, string>>

/** `key`'s SDK, as emitted. */
function emitted(key: Gated): Files {
	const fixture: CSharpFixture = FIXTURES[key]
	if (!("document" in fixture)) throw new Error(`${key} is not a document fixture`)
	return generateCSharpSdk(fixture.document(), fixture.options).files
}

/** `key` mapped over every gated fixture. */
const each = <T>(of: (key: Gated) => T): Record<Gated, T> =>
	Object.fromEntries(GATED.map((key) => [key, of(key)])) as Record<Gated, T>

/** The files a gate's `path(line,col): …` lines name, each once, sorted. */
const named = (lines: readonly string[]) =>
	[...new Set(lines.map((line) => /^([^(]+)\(/.exec(line)?.[1] ?? line))].sort()

/** `dotnet format whitespace --folder --verify-no-changes` over `files` written into a fresh dir: the files it names. */
function formatGate(files: Files): string[] {
	const dir = mkdtempSync(join(csharpCacheDir("tmp"), "fmt-"))
	try {
		for (const [name, text] of Object.entries(files)) {
			mkdirSync(dirname(join(dir, "src", name)), { recursive: true })
			writeFileSync(join(dir, "src", name), text)
		}
		const run = runDotnet(["format", "whitespace", "src", "--folder", "--verify-no-changes", "-v", "q"], { cwd: dir })
		const lines = `${run.stdout}${run.stderr}`.split("\n").filter((line) => / error WHITESPACE: /.test(line))
		return run.status === 0 ? [] : named(lines.map((line) => line.replace(`${join(dir, "src")}/`, "")))
	} finally {
		rmSync(dir, { force: true, recursive: true })
	}
}

describe.skipIf(!DOTNET)("the build gate: every emitted SDK builds clean", () => {
	it("builds every document fixture with no diagnostic: warnings as errors, nullable, AOT and trim analyzers, the doc file", () => {
		const outcomes = each((key) => {
			const sdk = compiledCSharp(key)
			return { built: sdk.built, diagnostics: sdk.diagnostics }
		})
		expect(outcomes).toEqual(each(() => ({ built: true, diagnostics: [] })))
	}, 600_000)
})

describe.skipIf(!DOTNET)("the format gate: dotnet format whitespace leaves nothing to change", () => {
	it("passes every document fixture's SDK, its vendored runtime included", () => {
		expect(each((key) => compiledCSharp(key).format())).toEqual(each(() => []))
	}, 600_000)

	it("passes the test driver's sources under their own root .editorconfig", () => {
		const run = runDotnet(["format", "whitespace", "driver", "--folder", "--verify-no-changes", "-v", "q"], {
			cwd: join(import.meta.dirname, "__fixtures__"),
		})
		expect(run.status, `${run.stdout}${run.stderr}`).toBe(0)
	}, 120_000)
})

describe.skipIf(!DOTNET)("the long-name SDK (bit 21 i7a)", () => {
	// bit 21 i7a: red-first clean
	it("builds clean and leaves the format gate nothing to change in any file: the client, its safe mirror, the types, the context", () => {
		const files = emitted("long")
		const sdk = compiledCSharp("long")
		/* not vacuous: the gate writes every file, and the client (its client.Safe mirror in it), the types and the context run past 120 */
		const long = (name: string) => (files[name] ?? "").split("\n").filter((line) => line.length > 120).length
		const safe = [...(files["Client.cs"] ?? "").matchAll(/^public sealed class Safe\w+Resource$/gm)].length
		expect({
			built: sdk.built,
			diagnostics: sdk.diagnostics,
			format: sdk.format(),
			pastWidth: ["Client.cs", "JsonContext.cs", "Types.cs"].filter((name) => long(name) > 0),
			safe,
			written: readdirSync(sdk.src, { encoding: "utf8", recursive: true })
				.filter((name) => !statSync(join(sdk.src, name)).isDirectory())
				.sort(),
		}).toEqual({
			built: true,
			diagnostics: [],
			format: [],
			pastWidth: ["Client.cs", "JsonContext.cs", "Types.cs"],
			safe: 11,
			written: Object.keys(files).sort(),
		})
	}, 600_000)
})

describe("what the gates reach", () => {
	it("vendors the runtime as committed into every SDK: Runtime/ is runtimeFiles' text for its ops' mix, in the SDK's namespace", () => {
		const vendored = each((key) => {
			const files = emitted(key)
			const manifest = Object.entries(files).find(([name]) => name.endsWith(".csproj"))?.[1] ?? ""
			const namespace = /<RootNamespace>([^<]+)<\/RootNamespace>/.exec(manifest)?.[1] ?? ""
			const runtime = Object.entries(files).filter(([name]) => name.startsWith("Runtime/"))
			return { expected: runtimeFiles(MIXES[key] ?? HTTP_ONLY, namespace), namespace, runtime }
		})
		for (const [key, { expected, namespace, runtime }] of Object.entries(vendored)) {
			expect(namespace, key).not.toBe("")
			expect(Object.keys(expected).length, key).toBeGreaterThan(0)
			expect(Object.fromEntries(runtime), key).toEqual(
				Object.fromEntries(Object.entries(expected).map(([name, text]) => [`Runtime/${name}`, text])),
			)
		}
	})
})

describe.skipIf(!DOTNET)("the gates can fail", () => {
	it("fails the canary: CS0168 under warnings as errors, and the format gate names its mis-indented file", () => {
		const canary = compiledCSharp("canary")
		const codes = canary.diagnostics.map((line) => /\): error (CS\d+): /.exec(line)?.[1] ?? line)
		expect({ built: canary.built, codes, format: named(canary.format()) }).toEqual({
			built: false,
			codes: ["CS0168"],
			format: ["Canary.cs"],
		})
	}, 300_000)

	it("is not vacuous: one method of surface's Client.cs at a 3-space indent fails the format gate, marker and all", () => {
		const files = emitted("surface")
		const lines = (files["Client.cs"] ?? "").split("\n")
		const at = lines.findIndex((line) => /^ {4}public \S.*Async\(.*\) =>$/.test(line))
		expect(at, "a one-line method signature in Client.cs").toBeGreaterThan(0)
		lines[at] = (lines[at] as string).slice(1)
		/* the gate's own run over the mutant's files: the registry alone feeds the build gate (G17, csharp-toolchain) */
		expect({ format: formatGate({ ...files, "Client.cs": lines.join("\n") }), marker: lines[0] }).toEqual({
			format: ["Client.cs"],
			marker: MARKER,
		})
		/* and the same run passes surface's files as emitted, so only the indent fails it */
		expect(formatGate(files)).toEqual([])
	}, 300_000)
})

/* every way a C# project can silence a diagnostic or mark code generated, which Roslyn's analyzers and the format
 * gate then skip: a pragma, a suppression attribute, an auto-generated header, the GeneratedCode attribute, a
 * nullable opt-out, an .editorconfig severity or generated_code key, and the manifest switches that lower or turn
 * off a warning or an analyzer; `<NoWarn>` is held apart, to the one CS1591 switch (Fb4) */
const SUPPRESSIONS: readonly (readonly [string, RegExp])[] = [
	["#pragma", /#pragma\b/],
	["SuppressMessage", /SuppressMessage/],
	["<auto-generated", /<auto-?generated/i],
	["GeneratedCode", /\[\s*(?:[\w.]*\.)?GeneratedCode(?:Attribute)?\s*\(/],
	["#nullable disable", /^\s*#nullable\s+disable/m],
	["dotnet_diagnostic", /dotnet_(?:analyzer_)?diagnostic/],
	["generated_code", /^\s*generated_code\s*=/m],
	[
		"a warning or analyzer switch",
		/<(?:WarningsNotAsErrors|WarningLevel|RunAnalyzers|RunAnalyzersDuringBuild|EnableNETAnalyzers|EnableTrimAnalyzer|EnableAotAnalyzer|EnableSingleFileAnalyzer|SuppressTrimAnalysisWarnings)>/,
	],
]

/* the file names Roslyn treats as generated code whatever they hold */
const GENERATED_NAME = /(?:^|\/)TemporaryGeneratedFile_|\.(?:designer|generated|g|g\.i)\.cs$/i

const NO_WARN = "<NoWarn>$(NoWarn);CS1591</NoWarn>"

/** What in `text`, named `name`, suppresses a diagnostic or marks code generated: `name: what`, each finding. */
function suppressions(name: string, text: string): string[] {
	const found = SUPPRESSIONS.filter(([, pattern]) => pattern.test(text)).map(([what]) => `${name}: ${what}`)
	const noWarn = [...text.matchAll(/<NoWarn>[\s\S]*?<\/NoWarn>|<NoWarn\b[^>]*\/>/g)].map((match) => match[0])
	const other = noWarn.filter((tag) => tag !== NO_WARN).map((tag) => `${name}: ${tag}`)
	return [...found, ...other, ...(GENERATED_NAME.test(name) ? [`${name}: a generated file name`] : [])]
}

describe("no suppression", () => {
	it("emits no pragma, suppression, generated mark or NoWarn but CS1591 in any SDK or runtime file", () => {
		const sdks = GATED.flatMap((key) => Object.entries(emitted(key)).map(([name, text]) => [`${key}/${name}`, text]))
		const runtime = Object.entries(runtimeFiles({ realtime: true, ws: true }, "Acme")).map(([name, text]) => [
			`Runtime/${name}`,
			text,
		])
		const texts = [...sdks, ...runtime] as [string, string][]
		expect(texts.filter(([name]) => name.endsWith(".csproj")).length).toBe(GATED.length)
		expect(texts.flatMap(([name, text]) => suppressions(name, text))).toEqual([])
		/* the manifest's one switch is there, so the NoWarn rule is not vacuous */
		expect(texts.filter(([, text]) => text.includes(NO_WARN)).length).toBe(GATED.length)
	})

	it("holds the detector to each form: one finding per suppression, none for the CS1591 switch", () => {
		const cases: readonly (readonly [string, string])[] = [
			["A.cs", "#pragma warning disable CS0168\n"],
			["A.cs", '[UnconditionalSuppressMessage("Trimming", "IL2026")]\n'],
			["A.cs", "// <autogenerated />\n"],
			["A.cs", '[System.CodeDom.Compiler.GeneratedCode("honey", "1")]\n'],
			["A.cs", "#nullable disable\n"],
			[".editorconfig", "dotnet_diagnostic.CS0168.severity = none\n"],
			[".editorconfig", "generated_code = true\n"],
			["A.csproj", "<EnableTrimAnalyzer>false</EnableTrimAnalyzer>\n"],
			["A.csproj", "<NoWarn>$(NoWarn);CS1591;IL2026</NoWarn>\n"],
			["Types.g.cs", "\n"],
		]
		expect(cases.map(([name, text]) => suppressions(name, text).length)).toEqual(cases.map(() => 1))
		expect(suppressions("A.csproj", `${NO_WARN}\n`)).toEqual([])
		expect(suppressions("Client.cs", `${MARKER}\n`)).toEqual([])
	})
})

/* the BCL names emitted text spells unqualified (§4.7's closed list), by namespace: a using the emitter writes is
 * used when its file spells one of them; any other namespace names nothing an emitted file spells */
const SPELLED: Readonly<Record<string, readonly string[]>> = {
	System: ["Exception", "Func", "IDisposable", "Object", "String", "Type"],
	"System.Collections.Generic": ["IReadOnlyDictionary", "IReadOnlyList"],
	"System.Text.Json": [
		"JsonElement",
		"JsonException",
		"JsonSerializer",
		"JsonSerializerOptions",
		"JsonTokenType",
		"Utf8JsonReader",
		"Utf8JsonWriter",
	],
	"System.Text.Json.Serialization": [
		"JsonConverter",
		"JsonIgnore",
		"JsonIgnoreCondition",
		"JsonPropertyName",
		"JsonSerializable",
		"JsonSerializerContext",
		"JsonSourceGenerationOptions",
		"JsonUnmappedMemberHandling",
	],
	"System.Text.Json.Serialization.Metadata": ["JsonTypeInfo"],
	"System.Threading": ["CancellationToken"],
	"System.Threading.Tasks": ["Task"],
}

/* the files the emitter writes, whose usings it chooses per file (§4.4); the runtime's are committed text */
const WRITTEN = ["Client.cs", "JsonContext.cs", "Types.cs"]

/** `text`'s using directives: each namespace, in file order. */
const usingsOf = (text: string) => [...text.matchAll(/^using ([^;=\s]+);$/gm)].map((match) => match[1] as string)

/** `text` without its using lines, string and char literals, and comments: the code that spells names. */
const codeOf = (text: string) =>
	text
		.replace(/^using [^;]+;$/gm, "")
		.replace(/"(?:[^"\\\n]|\\.)*"/g, '""')
		.replace(/'(?:[^'\\\n]|\\.)'/g, "''")
		.replace(/\/\/.*$/gm, "")

/** Whether `code` spells `name` (or `nameAttribute`) as a type, not as a member after a dot. */
const spells = (code: string, name: string) => new RegExp(`(?<![.\\w])${name}(?:Attribute)?\\b`).test(code)

/** What is wrong with `name`'s usings: out of code-unit order, and (for an emitter-written file) one unused. */
function usingFindings(name: string, text: string): string[] {
	const usings = usingsOf(text)
	const sorted = [...usings].sort()
	const order = usings.join() === sorted.join() ? [] : [`${name}: usings ${usings.join(", ")} are not sorted`]
	if (!WRITTEN.includes(name.split("/").pop() as string)) return order
	const code = codeOf(text)
	const unused = usings.filter((ns) => !(SPELLED[ns] ?? []).some((spelled) => spells(code, spelled)))
	return [...order, ...unused.map((ns) => `${name}: using ${ns} is unused`)]
}

/** A file of `usings` over `code`, for the detector's own cases. */
const client = (usings: string, code: string) => `${MARKER}\n${usings}\nnamespace Acme;\n\n${code}\n`

describe("usings sorted", () => {
	it("writes every file's usings in code-unit order, and each emitter-written one used", () => {
		const cs = GATED.flatMap((key) =>
			Object.entries(emitted(key))
				.filter(([name]) => name.endsWith(".cs"))
				.map(([name, text]) => [`${key}/${name}`, text] as const),
		)
		expect(cs.flatMap(([, text]) => usingsOf(text)).length).toBeGreaterThan(0)
		expect(cs.flatMap(([name, text]) => usingFindings(name, text))).toEqual([])
	})

	it("holds the detector to both rules: an unsorted pair, an unused using, and a name only a member spells", () => {
		const task = "public sealed class C\n{\n    public Task RunAsync() => Task.CompletedTask;\n}"
		expect(usingFindings("x/Client.cs", client("using System.Threading.Tasks;", task))).toEqual([])
		expect(usingFindings("x/Client.cs", client("using System.Threading.Tasks;\nusing System;", task))).toEqual([
			"x/Client.cs: usings System.Threading.Tasks, System are not sorted",
			"x/Client.cs: using System is unused",
		])
		const member =
			'public static class C\n{\n    public static object X => Ctx.Default.String; // Task\n    const string T = "Task";\n}'
		expect(usingFindings("x/Client.cs", client("using System;\nusing System.Threading.Tasks;", member))).toEqual([
			"x/Client.cs: using System is unused",
			"x/Client.cs: using System.Threading.Tasks is unused",
		])
		/* the runtime's usings are committed text: sorted, but not held to the emitter's spelled names */
		expect(usingFindings("x/Runtime/Transport.cs", client("using System.Net.Http;", task))).toEqual([])
	})
})
